create extension if not exists pgcrypto;
create type public.app_role as enum ('student','teacher','admin');
create type public.assignment_status as enum ('draft','published','closed');
create type public.submission_status as enum ('not_started','submitted','returned');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, role public.app_role not null default 'student', preferred_level text check (preferred_level in ('SL','HL','SL and HL')), study_goals text[] not null default '{}', timezone text not null default 'UTC', onboarding_completed boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.user_settings (user_id uuid primary key references public.profiles(id) on delete cascade, settings jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.lesson_progress (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, lesson_slug text not null, completion_percentage numeric(5,2) not null default 0 check(completion_percentage between 0 and 100), completed_at timestamptz, last_position jsonb not null default '{}'::jsonb, seconds_spent integer not null default 0 check(seconds_spent >= 0), mastery_score numeric(5,2) check(mastery_score between 0 and 100), confidence smallint check(confidence between 1 and 5), last_studied_at timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, lesson_slug));
create table public.topic_mastery (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, topic_slug text not null, mastery_score numeric(5,2) not null default 0 check(mastery_score between 0 and 100), confidence smallint check(confidence between 1 and 5), attempt_count integer not null default 0 check(attempt_count >= 0), last_assessed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, topic_slug));
create table public.quiz_attempts (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, quiz_key text not null, topic_slug text, difficulty text, started_at timestamptz not null default now(), completed_at timestamptz, seconds_spent integer not null default 0 check(seconds_spent >= 0), awarded_marks numeric(8,2) not null default 0, maximum_marks numeric(8,2) not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.question_attempts (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, quiz_attempt_id uuid references public.quiz_attempts(id) on delete set null, question_key text not null, topic_slug text, difficulty text, student_response jsonb not null default '{}'::jsonb, is_correct boolean, awarded_marks numeric(8,2), maximum_marks numeric(8,2), seconds_spent integer not null default 0 check(seconds_spent >= 0), hints_used integer not null default 0 check(hints_used >= 0), feedback text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.quiz_answers (id uuid primary key default gen_random_uuid(), quiz_attempt_id uuid not null references public.quiz_attempts(id) on delete cascade, question_attempt_id uuid references public.question_attempts(id) on delete cascade, question_key text not null, answer jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.bookmarks (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, content_type text not null, content_key text not null, note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, content_type, content_key));
create table public.flashcard_progress (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, card_key text not null, due_at timestamptz not null default now(), interval_days integer not null default 0 check(interval_days >= 0), ease numeric(4,2) not null default 2.5 check(ease between 1.3 and 3.5), repetitions integer not null default 0, lapses integer not null default 0, last_reviewed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, card_key));
create table public.study_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, started_at timestamptz not null default now(), ended_at timestamptz, seconds_spent integer not null default 0 check(seconds_spent >= 0), context jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.revision_plans (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, title text not null, target_date date, exam_date date, weekly_minutes integer check(weekly_minutes >= 0), weak_topics text[] not null default '{}', status text not null default 'active' check(status in ('draft','active','archived','complete')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.revision_tasks (id uuid primary key default gen_random_uuid(), plan_id uuid not null references public.revision_plans(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, title text not null, topic_slug text, due_at timestamptz, estimated_minutes integer check(estimated_minutes >= 0), completed_at timestamptz, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.ai_conversations (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, title text not null default 'New PHY conversation', lesson_slug text, topic_slug text, context jsonb not null default '{}'::jsonb, model text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.ai_messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.ai_conversations(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, role text not null check(role in ('user','assistant','system')), content text not null, metadata jsonb not null default '{}'::jsonb, input_tokens integer check(input_tokens >= 0), output_tokens integer check(output_tokens >= 0), cost_microusd integer check(cost_microusd >= 0), referenced_content_ids text[] not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.teacher_classes (id uuid primary key default gen_random_uuid(), teacher_id uuid not null references public.profiles(id) on delete cascade, name text not null, join_code text not null unique default encode(gen_random_bytes(5),'hex'), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.class_memberships (id uuid primary key default gen_random_uuid(), class_id uuid not null references public.teacher_classes(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, role text not null default 'student' check(role in ('student','teacher')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(class_id,user_id));
create table public.assignments (id uuid primary key default gen_random_uuid(), class_id uuid not null references public.teacher_classes(id) on delete cascade, teacher_id uuid not null references public.profiles(id) on delete cascade, title text not null, instructions text, content jsonb not null default '{}'::jsonb, due_at timestamptz, status public.assignment_status not null default 'draft', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.assignment_submissions (id uuid primary key default gen_random_uuid(), assignment_id uuid not null references public.assignments(id) on delete cascade, student_id uuid not null references public.profiles(id) on delete cascade, content jsonb not null default '{}'::jsonb, status public.submission_status not null default 'not_started', submitted_at timestamptz, teacher_feedback text, awarded_marks numeric(8,2), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(assignment_id,student_id));

create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
create or replace function public.is_class_teacher(target_class uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.teacher_classes where id=target_class and teacher_id=auth.uid()) $$;
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
do $$ declare t text; begin foreach t in array array['profiles','user_settings','lesson_progress','topic_mastery','quiz_attempts','question_attempts','quiz_answers','bookmarks','flashcard_progress','study_sessions','revision_plans','revision_tasks','ai_conversations','ai_messages','teacher_classes','class_memberships','assignments','assignment_submissions'] loop execute format('create trigger %I before update on public.%I for each row execute function public.set_updated_at()',t||'_updated_at',t); end loop; end $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name','')); insert into public.user_settings(user_id) values(new.id); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create index lesson_progress_user_lesson_idx on public.lesson_progress(user_id,lesson_slug); create index question_attempts_user_topic_idx on public.question_attempts(user_id,topic_slug); create index flashcard_due_idx on public.flashcard_progress(user_id,due_at); create index ai_messages_conversation_idx on public.ai_messages(conversation_id,created_at); create index memberships_user_idx on public.class_memberships(user_id);
alter table public.profiles enable row level security; alter table public.user_settings enable row level security; alter table public.lesson_progress enable row level security; alter table public.topic_mastery enable row level security; alter table public.quiz_attempts enable row level security; alter table public.question_attempts enable row level security; alter table public.quiz_answers enable row level security; alter table public.bookmarks enable row level security; alter table public.flashcard_progress enable row level security; alter table public.study_sessions enable row level security; alter table public.revision_plans enable row level security; alter table public.revision_tasks enable row level security; alter table public.ai_conversations enable row level security; alter table public.ai_messages enable row level security; alter table public.teacher_classes enable row level security; alter table public.class_memberships enable row level security; alter table public.assignments enable row level security; alter table public.assignment_submissions enable row level security;
create policy profiles_owner on public.profiles for all using(id=auth.uid() or public.is_admin()) with check(id=auth.uid() or public.is_admin());
create policy settings_owner on public.user_settings for all using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin());
do $$ declare t text; begin foreach t in array array['lesson_progress','topic_mastery','quiz_attempts','question_attempts','bookmarks','flashcard_progress','study_sessions','revision_plans','revision_tasks','ai_conversations'] loop execute format('create policy %I on public.%I for all using (user_id=auth.uid() or public.is_admin()) with check (user_id=auth.uid() or public.is_admin())',t||'_owner',t); end loop; end $$;
create policy quiz_answers_owner on public.quiz_answers for all using (exists(select 1 from public.quiz_attempts q where q.id=quiz_attempt_id and q.user_id=auth.uid()) or public.is_admin()) with check (exists(select 1 from public.quiz_attempts q where q.id=quiz_attempt_id and q.user_id=auth.uid()) or public.is_admin());
create policy ai_messages_owner on public.ai_messages for all using (user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin());
create policy classes_teacher on public.teacher_classes for all using(teacher_id=auth.uid() or public.is_admin()) with check(teacher_id=auth.uid() or public.is_admin());
create policy memberships_member_or_teacher on public.class_memberships for select using(user_id=auth.uid() or public.is_class_teacher(class_id) or public.is_admin()); create policy memberships_self_join on public.class_memberships for insert with check(user_id=auth.uid() or public.is_class_teacher(class_id) or public.is_admin());
create policy assignments_class_access on public.assignments for select using(public.is_class_teacher(class_id) or exists(select 1 from public.class_memberships m where m.class_id=assignments.class_id and m.user_id=auth.uid()) or public.is_admin()); create policy assignments_teacher_write on public.assignments for all using(public.is_class_teacher(class_id) or public.is_admin()) with check(public.is_class_teacher(class_id) or public.is_admin());
create policy submissions_student_or_teacher on public.assignment_submissions for select using(student_id=auth.uid() or exists(select 1 from public.assignments a where a.id=assignment_id and public.is_class_teacher(a.class_id)) or public.is_admin()); create policy submissions_student_write on public.assignment_submissions for insert with check(student_id=auth.uid()); create policy submissions_student_update on public.assignment_submissions for update using(student_id=auth.uid()) with check(student_id=auth.uid());
